#include <iostream>

bool esPrimo(int n) {
    if (n < 2) {
        return false;
    }
    for (int d = 2; d * d <= n; ++d) {
        if (n % d == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    int encontrados = 0;
    for (int n = 2; n < 30; ++n) {
        if (esPrimo(n)) {
            std::cout << n << ' ';
            ++encontrados;
        }
    }
    std::cout << "\nTotal: " << encontrados << '\n';
    return 0;
}

