#include <iostream>

double celsiusAFahrenheit(double celsius) {
    return celsius * 9.0 / 5.0 + 32.0;
}

int main() {
    std::cout << celsiusAFahrenheit(0.0) << '\n';
    std::cout << celsiusAFahrenheit(25.0) << '\n';
    std::cout << celsiusAFahrenheit(100.0) << '\n';
    return 0;
}

#include <iostream>

int sumaDivisores(int n) {
    int suma = 0;
    for (int d = 1; d < n; ++d) {
        if (n % d == 0) {
            suma += d;
        }
    }
    return suma;
}

bool esPerfecto(int n) {
    return n > 1 && sumaDivisores(n) == n;
}

int main() {
    int numeros[3] = {6, 28, 12};
    for (int i = 0; i < 3; ++i) {
        std::cout << numeros[i] << ": " << (esPerfecto(numeros[i]) ? "si" : "no") << '\n';
    }
    return 0;
}

